{
  "id": "R1",
  "summary_ko": "바이알들이 허공에서 갑자기 나타남",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "Vials simply appear out of thin air",
      "symptom_ko": "바이알들이 허공에서 갑자기 나타남",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Vials",
      "explicit_detail_evidence": [
        "appear out of thin air"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "새로운 각도이기는 하나 실험실 구성이 다르고, 요청된 대로 원래의 주 실험실이 다양한 각도에서 실제로 보이지 않음.",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "While this IS a new angle, it is also a different laboratory setup.",
      "symptom_ko": "새로운 각도이나 실험실 구성/설정 자체가 달라짐",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "laboratory setup",
      "explicit_detail_evidence": [
        "different laboratory setup"
      ],
      "missing_details_ko": ""
    },
    {
      "id": "R2.S2",
      "evidence": "The main one isn't actually shown from different angles as requested.",
      "symptom_ko": "요청된 것과 달리 주요 실험실이 실제로 다른 각도에서 보여지지 않음",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The main one",
      "explicit_detail_evidence": [
        "isn't actually shown from different angles as requested"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R4",
  "summary_ko": "두 번째 장면에서 그래프를 표시하는 컴퓨터 모니터의 위치가 그의 뒤쪽에서 앞쪽으로 바뀜",
  "claims": [
    {
      "id": "R4.S1",
      "evidence": "Computer monitors showing the graphs switch from behind him to in front of him in the second scene",
      "symptom_ko": "컴퓨터 모니터의 위치가 뒤쪽에서 앞쪽으로 바뀜",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Computer monitors showing the graphs",
      "explicit_detail_evidence": [
        "switch from behind him to in front of him in the second scene"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "target_relation": "different",
      "reference_claim_ids": ["R1.S1"],
      "reference_evidence": "Vials simply appear out of thin air",
      "candidate_evidence": "The scientist's right hand holding a test tube warps and shifts position unnaturally as he holds it up.",
      "basis": "explicit_separation",
      "reason_ko": "참조 텍스트는 바이알(Vials)이 허공에서 갑자기 생겨나는 결함을 명시하고 있는 반면, 후보 텍스트는 과학자의 오른손이 시험관을 든 채 왜곡되고 부자연스럽게 위치를 이동하는 신체 왜곡 결함을 기술하고 있습니다. 대상 객체(바이알 자체의 생성 vs 과학자의 오른손 및 시험관 위치 왜곡)와 이상 현상 내용이 서로 명확히 구분되는 별개의 결함이므로 명시적 분리에 해당합니다."
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": [
        "R3.S1"
      ],
      "reference_evidence": "Instead of cutting to a third scene or position, they return to the original position",
      "candidate_evidence": "A test tube appears in the scientist's left hand without being retrieved from the rack.",
      "basis": "explicit_separation",
      "reason_ko": "참조 텍스트 R3.S1은 카메라의 장면 전환 실패 및 원래 위치 복귀 문제를 다루는 반면, 후보 C3은 과학자의 왼손에 시험관이 갑자기 생성되는 객체 출현 결함을 기술하고 있어 서로 다른 현상/결함에 해당합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "target_relation": "different",
      "reference_claim_ids": [
        "R3.S1"
      ],
      "reference_evidence": "Instead of cutting to a third scene or position, they return to the original position",
      "candidate_evidence": "The scientist's right hand holding a test tube warps and shifts position unnaturally as he holds it up.",
      "basis": "explicit_separation",
      "reason_ko": "참조 텍스트 R3.S1은 카메라/씬이 세 번째 장면으로 전환되지 않고 원래 위치로 돌아오는 씬 편집 결함을 기술하는 반면, 후보 C4는 시험관을 든 오른손의 왜곡 및 부자연스러운 위치 이동이라는 신체 부위 변형 결함을 기술하고 있어 명확히 구분됩니다."
    }
  ]
}

